PRAGMA foreign_keys = ON;

CREATE TABLE tenants (id TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('PLATFORM','ORGANIZATION')), status TEXT NOT NULL CHECK (status IN ('ACTIVE','DELETING','DELETED')), deletion_epoch INTEGER NOT NULL DEFAULT 0 CHECK (deletion_epoch >= 0), created_at TEXT NOT NULL);
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE tenant_memberships (tenant_id TEXT NOT NULL, user_id TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('OWNER','ADMIN','MEMBER','DESIGNATED_REVIEWER','SUPER_ADMIN','OPS_ADMIN','VIEWER')), created_at TEXT NOT NULL, PRIMARY KEY (tenant_id,user_id), FOREIGN KEY (tenant_id) REFERENCES tenants(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE credentials (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('PASSWORD','SERVICE')), secret_hash TEXT NOT NULL, created_at TEXT NOT NULL, revoked_at TEXT, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, tenant_id TEXT NOT NULL, expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (tenant_id,user_id) REFERENCES tenant_memberships(tenant_id,user_id));
CREATE TABLE api_tokens (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, tenant_id TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (tenant_id,user_id) REFERENCES tenant_memberships(tenant_id,user_id));
CREATE TABLE reviewer_assignments (id TEXT PRIMARY KEY, tenant_id TEXT, reviewer_id TEXT NOT NULL, gate TEXT NOT NULL CHECK (gate IN ('T1','T2','T3','T4','T5','T6')), scope TEXT NOT NULL CHECK (scope IN ('TENANT','RELEASE')), created_at TEXT NOT NULL, FOREIGN KEY (tenant_id) REFERENCES tenants(id), FOREIGN KEY (reviewer_id) REFERENCES users(id));
CREATE TABLE cas_objects (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, sha256 TEXT NOT NULL, content_type TEXT NOT NULL, size_bytes INTEGER NOT NULL CHECK (size_bytes >= 0), purpose TEXT NOT NULL, retention_until TEXT NOT NULL, UNIQUE (tenant_id,id), FOREIGN KEY (tenant_id) REFERENCES tenants(id));
CREATE TABLE uploads (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, filename TEXT NOT NULL, content_type TEXT NOT NULL, size_bytes INTEGER NOT NULL CHECK (size_bytes >= 0), state TEXT NOT NULL CHECK (state IN ('PENDING','QUARANTINED','ACCEPTED','EXPIRED')), cas_object_id TEXT, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, UNIQUE (tenant_id,id), FOREIGN KEY (tenant_id) REFERENCES tenants(id), FOREIGN KEY (tenant_id,cas_object_id) REFERENCES cas_objects(tenant_id,id));
CREATE TABLE jobs (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, creator_id TEXT NOT NULL, upload_id TEXT NOT NULL, scene_id TEXT NOT NULL, state TEXT NOT NULL CHECK (state IN ('QUEUED','PREPARING','RENDERING','COMPLETED','CANCELLED','FAILED')), attempt INTEGER NOT NULL DEFAULT 0 CHECK (attempt >= 0), deletion_epoch INTEGER NOT NULL CHECK (deletion_epoch >= 0), created_at TEXT NOT NULL, UNIQUE (tenant_id,id), FOREIGN KEY (tenant_id) REFERENCES tenants(id), FOREIGN KEY (tenant_id,creator_id) REFERENCES tenant_memberships(tenant_id,user_id), FOREIGN KEY (tenant_id,upload_id) REFERENCES uploads(tenant_id,id));
CREATE TABLE job_attempts (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, job_id TEXT NOT NULL, number INTEGER NOT NULL CHECK (number > 0), state TEXT NOT NULL CHECK (state IN ('QUEUED','RUNNING','COMPLETED','FAILED','CANCELLED')), created_at TEXT NOT NULL, UNIQUE (tenant_id,id), UNIQUE (tenant_id,job_id,number), FOREIGN KEY (tenant_id,job_id) REFERENCES jobs(tenant_id,id));
CREATE TABLE job_leases (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, job_id TEXT NOT NULL, attempt_id TEXT NOT NULL, worker_id TEXT NOT NULL, acquired_at TEXT NOT NULL, expires_at TEXT NOT NULL, released_at TEXT, UNIQUE (tenant_id,job_id,attempt_id), FOREIGN KEY (tenant_id,job_id) REFERENCES jobs(tenant_id,id), FOREIGN KEY (tenant_id,attempt_id) REFERENCES job_attempts(tenant_id,id));
CREATE TABLE reviews (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, job_id TEXT NOT NULL, gate TEXT NOT NULL CHECK (gate IN ('T1','T2','T3','T4','T5','T6')), status TEXT NOT NULL CHECK (status IN ('PENDING','APPROVED','REJECTED')), created_at TEXT NOT NULL, FOREIGN KEY (tenant_id,job_id) REFERENCES jobs(tenant_id,id));
CREATE TABLE receipts (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, job_id TEXT NOT NULL, attempt_id TEXT NOT NULL, sequence INTEGER NOT NULL CHECK (sequence > 0), gate TEXT NOT NULL CHECK (gate IN ('T1','T2','T3','T4','T5','T6')), decision TEXT NOT NULL CHECK (decision IN ('PASS','FAIL','NEEDS_CHOICE','REJECT')), actor_id TEXT NOT NULL, predecessor_id TEXT, artifact_cas_ids TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL, UNIQUE (tenant_id,job_id,gate), UNIQUE (tenant_id,attempt_id,sequence), FOREIGN KEY (tenant_id,job_id) REFERENCES jobs(tenant_id,id), FOREIGN KEY (tenant_id,attempt_id) REFERENCES job_attempts(tenant_id,id), FOREIGN KEY (actor_id) REFERENCES users(id), FOREIGN KEY (predecessor_id) REFERENCES receipts(id));
CREATE TABLE audit_events (id TEXT PRIMARY KEY, tenant_id TEXT, actor_id TEXT NOT NULL, action TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT NOT NULL, decision TEXT NOT NULL, correlation_id TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY (tenant_id) REFERENCES tenants(id), FOREIGN KEY (actor_id) REFERENCES users(id));
CREATE TABLE tenant_quotas (tenant_id TEXT PRIMARY KEY, plan TEXT NOT NULL, limit_seconds INTEGER NOT NULL CHECK (limit_seconds >= 0), used_seconds INTEGER NOT NULL DEFAULT 0 CHECK (used_seconds >= 0), enforcement_state TEXT NOT NULL CHECK (enforcement_state IN ('ENFORCED','GRACE')), support_grant_expires_at TEXT, FOREIGN KEY (tenant_id) REFERENCES tenants(id));
CREATE TABLE idempotency_keys (tenant_id TEXT NOT NULL, key TEXT NOT NULL, request_hash TEXT NOT NULL, response_json TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (tenant_id,key), FOREIGN KEY (tenant_id) REFERENCES tenants(id));
CREATE TABLE exports (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, requested_by TEXT NOT NULL, state TEXT NOT NULL CHECK (state IN ('QUEUED','READY','EXPIRED','FAILED')), created_at TEXT NOT NULL, FOREIGN KEY (tenant_id) REFERENCES tenants(id), FOREIGN KEY (tenant_id,requested_by) REFERENCES tenant_memberships(tenant_id,user_id));
CREATE TABLE artifacts (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, export_id TEXT, cas_object_id TEXT NOT NULL, kind TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY (tenant_id) REFERENCES tenants(id), FOREIGN KEY (tenant_id,cas_object_id) REFERENCES cas_objects(tenant_id,id), FOREIGN KEY (export_id) REFERENCES exports(id));
CREATE TABLE authoring_ir_versions (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, scene_id TEXT NOT NULL, version INTEGER NOT NULL CHECK (version > 0), ir_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE (tenant_id,scene_id,version), FOREIGN KEY (tenant_id) REFERENCES tenants(id));
CREATE TABLE scene_ir_versions (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, scene_id TEXT NOT NULL, version INTEGER NOT NULL CHECK (version > 0), ir_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE (tenant_id,scene_id,version), FOREIGN KEY (tenant_id) REFERENCES tenants(id));
CREATE TABLE browser_pass_spec_versions (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, scene_id TEXT NOT NULL, version INTEGER NOT NULL CHECK (version > 0), spec_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE (tenant_id,scene_id,version), FOREIGN KEY (tenant_id) REFERENCES tenants(id));

CREATE TRIGGER tenants_epoch_monotonic BEFORE UPDATE OF deletion_epoch ON tenants WHEN NEW.deletion_epoch < OLD.deletion_epoch BEGIN SELECT RAISE(ABORT,'DELETION_EPOCH_DECREASE'); END;
CREATE TRIGGER tenants_id_immutable BEFORE UPDATE OF id ON tenants BEGIN SELECT RAISE(ABORT,'TENANT_ID_IMMUTABLE'); END;
CREATE TRIGGER receipts_append_only_update BEFORE UPDATE ON receipts BEGIN SELECT RAISE(ABORT,'RECEIPT_APPEND_ONLY'); END;
CREATE TRIGGER receipts_append_only_delete BEFORE DELETE ON receipts BEGIN SELECT RAISE(ABORT,'RECEIPT_APPEND_ONLY'); END;
CREATE TRIGGER audit_append_only_update BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT,'AUDIT_APPEND_ONLY'); END;
CREATE TRIGGER audit_append_only_delete BEFORE DELETE ON audit_events BEGIN SELECT RAISE(ABORT,'AUDIT_APPEND_ONLY'); END;
CREATE TRIGGER authoring_ir_append_only_update BEFORE UPDATE ON authoring_ir_versions BEGIN SELECT RAISE(ABORT,'IR_APPEND_ONLY'); END;
CREATE TRIGGER authoring_ir_append_only_delete BEFORE DELETE ON authoring_ir_versions BEGIN SELECT RAISE(ABORT,'IR_APPEND_ONLY'); END;
CREATE TRIGGER scene_ir_append_only_update BEFORE UPDATE ON scene_ir_versions BEGIN SELECT RAISE(ABORT,'IR_APPEND_ONLY'); END;
CREATE TRIGGER scene_ir_append_only_delete BEFORE DELETE ON scene_ir_versions BEGIN SELECT RAISE(ABORT,'IR_APPEND_ONLY'); END;
CREATE TRIGGER browser_spec_append_only_update BEFORE UPDATE ON browser_pass_spec_versions BEGIN SELECT RAISE(ABORT,'IR_APPEND_ONLY'); END;
CREATE TRIGGER browser_spec_append_only_delete BEFORE DELETE ON browser_pass_spec_versions BEGIN SELECT RAISE(ABORT,'IR_APPEND_ONLY'); END;
